import { readFile } from "node:fs/promises";
import { resolve } from "node:path";
import { ALL_TOOL_CONTRACTS, saveAgentLabels, saveExperiment, saveExperimentGroup, saveScenario, } from "bitfab-lib/mcp-contract";
import { errorResult, McpProxy } from "./mcpProxy.js";
function withLegacyExperimentKeys(args) {
    return {
        ...args,
        ...(args.experimentId === undefined
            ? {}
            : { testRunId: args.experimentId }),
        ...(args.experimentIds === undefined
            ? {}
            : { testRunIds: args.experimentIds }),
    };
}
const SOURCE_FIELDS = ["frameAt", "capturedAt", "windows", "coverage"];
function isObjectWithRecords(parsed) {
    return (typeof parsed === "object" &&
        parsed !== null &&
        "records" in parsed &&
        Array.isArray(parsed.records));
}
function sourcesInFile(parsed) {
    if (!("coverage" in parsed)) {
        return undefined;
    }
    return Object.fromEntries(SOURCE_FIELDS.filter((field) => field in parsed).map((field) => [
        field,
        parsed[field],
    ]));
}
function recordsInFile(parsed) {
    if (Array.isArray(parsed)) {
        return { records: parsed };
    }
    if (!isObjectWithRecords(parsed)) {
        return null;
    }
    const sources = sourcesInFile(parsed);
    return sources === undefined
        ? { records: parsed.records }
        : { records: parsed.records, sources };
}
async function readRecordsFile(recordsPath) {
    const fullPath = resolve(recordsPath);
    let contents;
    try {
        contents = await readFile(fullPath, "utf8");
    }
    catch (error) {
        return {
            error: `could not read recordsPath ${fullPath}: ${error instanceof Error ? error.message : String(error)}`,
        };
    }
    let parsed;
    try {
        parsed = JSON.parse(contents);
    }
    catch {
        return { error: `recordsPath ${fullPath} is not JSON.` };
    }
    const file = recordsInFile(parsed);
    return file === null
        ? {
            error: `recordsPath ${fullPath} holds neither an array of records nor an object with a records array.`,
        }
        : file;
}
export function createBitfabToolHandlers(platform, getConfig, pluginVersion) {
    const proxy = new McpProxy(platform, pluginVersion);
    function proxyToolCall(toolName, args) {
        return proxy.toolCall(getConfig(), toolName, withLegacyExperimentKeys(args));
    }
    async function handleSaveAgentLabels(args) {
        const { experimentId, labels } = args;
        return proxyToolCall("save_agent_labels", {
            experimentId,
            labels: labels.map((l) => l.originalTraceId !== undefined && l.sourceTraceId === undefined
                ? { ...l, sourceTraceId: l.originalTraceId }
                : l),
        });
    }
    async function handleSaveExperiment(args) {
        const { experimentId, name, notes, experimentGroupId } = args;
        if (name === undefined &&
            notes === undefined &&
            experimentGroupId === undefined) {
            return errorResult("Error saving experiment: provide name, notes, and/or experimentGroupId.");
        }
        return proxyToolCall("save_experiment", {
            experimentId,
            name,
            notes,
            experimentGroupId,
        });
    }
    async function handleSaveExperimentGroup(args) {
        const { experimentGroupId, experimentIds, name, notes } = args;
        if (experimentGroupId === undefined && experimentIds === undefined) {
            return errorResult("Error saving experiment group: experimentIds is required when creating an experiment group.");
        }
        if (experimentGroupId !== undefined && experimentIds !== undefined) {
            return errorResult("Error saving experiment group: experimentIds cannot be provided when editing an experiment group; editing does not change membership.");
        }
        if (experimentGroupId !== undefined &&
            name === undefined &&
            notes === undefined) {
            return errorResult("Error saving experiment group: provide name and/or notes when editing an experiment group.");
        }
        return proxyToolCall("save_experiment_group", {
            experimentGroupId,
            experimentIds,
            name,
            notes,
        });
    }
    async function handleSaveScenario(args) {
        const { recordsPath, ...rest } = args;
        if (recordsPath === undefined) {
            return proxyToolCall("save_scenario", rest);
        }
        if (rest.records !== undefined) {
            return errorResult("Error saving scenario: send records or recordsPath, not both.");
        }
        if (rest.sources !== undefined) {
            return errorResult("Error saving scenario: recordsPath sends the file's own sources, so send sources only with records.");
        }
        const read = await readRecordsFile(recordsPath);
        if ("error" in read) {
            return errorResult(`Error saving scenario: ${read.error}`);
        }
        return proxyToolCall("save_scenario", { ...rest, ...read });
    }
    const specialHandlers = {
        [saveAgentLabels.name]: handleSaveAgentLabels,
        [saveExperiment.name]: handleSaveExperiment,
        [saveExperimentGroup.name]: handleSaveExperimentGroup,
        [saveScenario.name]: handleSaveScenario,
    };
    const handlers = ALL_TOOL_CONTRACTS.map((contract) => ({
        contract,
        handle: specialHandlers[contract.name] ??
            ((args) => proxyToolCall(contract.name, args)),
    }));
    return { proxy, handlers };
}
